from typing import Any, Optional
from pydantic import BaseModel, Field


class ToolResult(BaseModel):
    """Result returned by tool execution."""
    success: bool = True
    payload: dict[str, Any] = Field(default_factory=dict)
    error: Optional[str] = None


class StepPlan(BaseModel):
    """Raw step generated by the LLM."""
    say: str = Field(description="One short spoken sentence in plain words, no symbols or markdown")
    tool: str = Field(description="Board tool name: write_text, plot_function, draw_shape, clear_board, unable")
    text: Optional[str] = Field(None, description="For write_text: text or formula to display on board")
    expression: Optional[str] = Field(None, description="For plot_function: e.g. x**2 - 4")
    x_min: Optional[float] = Field(-10.0, description="For plot_function minimum x")
    x_max: Optional[float] = Field(10.0, description="For plot_function maximum x")
    shape: Optional[str] = Field(None, description="For draw_shape: line, circle, triangle, or rectangle")
    unable_reason: Optional[str] = Field(None, description="For unable tool: reason why cannot answer")
    motion: str = Field(description="Motion name chosen from the discovered motion assets")


class TutorPlan(BaseModel):
    """Structured plan returned by the LLM."""
    found_in_book: bool = Field(description="True if textbook context answers the question")
    steps: list[StepPlan] = Field(description="2 to 4 steps in order")
    check_question: Optional[str] = Field(None, description="One short question for the student, or null")


class Step(BaseModel):
    """Finalized step ready for playback in frontend."""
    say: str
    audio_url: Optional[str] = None
    motion: str
    board: dict[str, Any]


class AskRequest(BaseModel):
    question: str
    session_id: Optional[str] = "default"
    provider: Optional[str] = None


class AskResponse(BaseModel):
    found_in_book: bool
    steps: list[Step]
    check_question: Optional[str] = None
